import{_ as i,o as l,c as p,a3 as e}from"./chunks/framework.DdpBa4_E.js";const d=JSON.parse('{"title":"作译者简介","description":"","frontmatter":{},"headers":[],"relativePath":"books/bei-taoyan-de-yongqi/71-作译者简介.md","filePath":"books/bei-taoyan-de-yongqi/71-作译者简介.md","lastUpdated":1794748679000}'),r={name:"books/bei-taoyan-de-yongqi/71-作译者简介.md"};function f(h,a,t,o,n,s){return l(),p("div",null,[...a[0]||(a[0]=[e('<h1 id="作译者简介" tabindex="-1">作译者简介 <a class="header-anchor" href="#作译者简介" aria-label="Permalink to &quot;作译者简介&quot;">​</a></h1><p>岸见一郎</p><p>哲学家。1956年生于京都，现居京都。高中时便以哲学为志向，进入大学后屡次到老师府上进行辩论。京都大学研究生院文学研究系博士课程满期退学。与专业哲学（西洋古代哲学、特别是柏拉图哲学）同时开始，于1989年起致力于研究阿德勒心理学。主要活动领域是阿德勒心理学及古代哲学的执笔与演讲，同时还在精神科医院为许多“青年”做心理辅导。日本阿德勒心理学会认定顾问。译著有阿尔弗雷德·阿德勒的《个人心理学讲义》和《人为什么会患神经病》，著有《阿德勒心理学入门》等多部作品。本书由其负责原案。</p><p>古贺史健</p><p>自由作家。1973年出生。以对话创作（问答体裁的执笔）为专长，出版过许多商务或纪实文学方面的畅销书。他创作的极具现场感与节奏感的采访稿广受好评。采访集《16岁的教科书》系列累计销量突破70万册。近30岁的时候邂逅阿德勒心理学，并被其颠覆常识的思想所震撼。之后，连续数年拜访京都的岸见一郎并向其请教阿德勒心理学的本质。本书中，他以希腊哲学的古典手法“对话篇”进行内容呈现。著有《想要让20岁的自己接受的文章讲义》。</p><p>渠海霞</p><p>女，1981年出生，日语语言文学硕士，现任教于山东省聊城大学外国语学院日语系。曾公开发表学术论文多篇，翻译出版《感动顾客的秘密——资生堂之“津田魔法”》《平衡计分卡实战手册》《一句话说服对方》《日产，这样赢得世界》《简明经济学读本》和《家庭日记——森友治家的故事》等书。</p><h2 id="table-of-contents" tabindex="-1">Table of Contents <a class="header-anchor" href="#table-of-contents" aria-label="Permalink to &quot;Table of Contents&quot;">​</a></h2><ul><li><p><a href="./01-原书信息">原书信息</a></p></li><li><p><a href="./02-相关内容">相关内容</a></p></li><li><p><a href="./03-本书的赞誉">本书的赞誉</a></p></li><li><p><a href="./04-推荐序一勇气的心理学">推荐序一 勇气的心理学</a></p></li><li><p><a href="./05-推荐序二自我的枷锁和解放">推荐序二 自我的枷锁和解放</a></p></li><li><p><a href="./06-推荐序三人唯有在能够感觉自己有价值时，才有勇气">推荐序三 人唯有在能够感觉自己有价值时，才有勇气</a></p></li><li><p><a href="./07-译者序">译者序</a></p></li><li><p><a href="./08-引言">引言</a></p></li><li><p><a href="./09-第一夜我们的不幸是谁的错？">第一夜 我们的不幸是谁的错？</a></p></li><li><p><a href="./10-不为人知的心理学“第三巨头”">不为人知的心理学“第三巨头”</a></p></li><li><p><a href="./11-再怎么“找原因”，也没法改变一个人">再怎么“找原因”，也没法改变一个人</a></p></li><li><p><a href="./12-心理创伤并不存在">心理创伤并不存在</a></p></li><li><p><a href="./13-愤怒都是捏造出来的">愤怒都是捏造出来的</a></p></li><li><p><a href="./14-弗洛伊德说错了">弗洛伊德说错了</a></p></li><li><p><a href="./15-苏格拉底和阿德勒">苏格拉底和阿德勒</a></p></li><li><p><a href="./16-你想“变成别人”吗？">你想“变成别人”吗？</a></p></li><li><p><a href="./17-你的不幸，皆是自己“选择”的">你的不幸，皆是自己“选择”的</a></p></li><li><p><a href="./18-人们常常下定决心“不改变”">人们常常下定决心“不改变”</a></p></li><li><p><a href="./19-你的人生取决于“当下”">你的人生取决于“当下”</a></p></li><li><p><a href="./20-第二夜一切烦恼都来自人际关系">第二夜 一切烦恼都来自人际关系</a></p></li><li><p><a href="./21-为什么讨厌自己？">为什么讨厌自己？</a></p></li><li><p><a href="./22-一切烦恼都是人际关系的烦恼">一切烦恼都是人际关系的烦恼</a></p></li><li><p><a href="./23-自卑感来自主观的臆造">自卑感来自主观的臆造</a></p></li><li><p><a href="./24-自卑情结只是一种借口">自卑情结只是一种借口</a></p></li><li><p><a href="./25-越自负的人越自卑">越自负的人越自卑</a></p></li><li><p><a href="./26-人生不是与他人的比赛">人生不是与他人的比赛</a></p></li><li><p><a href="./27-在意你长相的，只有你自己">在意你长相的，只有你自己</a></p></li><li><p><a href="./28-人际关系中的“权力斗争”与复仇">人际关系中的“权力斗争”与复仇</a></p></li><li><p><a href="./29-承认错误，不代表你失败了">承认错误，不代表你失败了</a></p></li><li><p><a href="./30-人生的三大课题：交友课题、工作课题以及爱的课题">人生的三大课题：交友课题、工作课题以及爱的课题</a></p></li><li><p><a href="./31-浪漫的红线和坚固的锁链">浪漫的红线和坚固的锁链</a></p></li><li><p><a href="./32-“人生谎言”教我们学会逃避">“人生谎言”教我们学会逃避</a></p></li><li><p><a href="./33-阿德勒心理学是“勇气的心理学”">阿德勒心理学是“勇气的心理学”</a></p></li><li><p><a href="./34-第三夜让干涉你生活的人见鬼去">第三夜 让干涉你生活的人见鬼去</a></p></li><li><p><a href="./35-自由就是不再寻求认可？">自由就是不再寻求认可？</a></p></li><li><p><a href="./36-要不要活在别人的期待中？">要不要活在别人的期待中？</a></p></li><li><p><a href="./37-把自己和别人的“人生课题”分开来">把自己和别人的“人生课题”分开来</a></p></li><li><p><a href="./38-那使父母也得放下孩子的课题">那使父母也得放下孩子的课题</a></p></li><li><p><a href="./39-放下别人的课题，烦恼轻轻飞走">放下别人的课题，烦恼轻轻飞走</a></p></li><li><p><a href="./40-砍断“格尔迪奥斯绳结”">砍断“格尔迪奥斯绳结”</a></p></li><li><p><a href="./41-对认可的追求，扼杀了自由">对认可的追求，扼杀了自由</a></p></li><li><p><a href="./42-自由就是被别人讨厌">自由就是被别人讨厌</a></p></li><li><p><a href="./43-人际关系“王牌”，握在你自己手里">人际关系“王牌”，握在你自己手里</a></p></li><li><p><a href="./44-第四夜要有被讨厌的勇气">第四夜 要有被讨厌的勇气</a></p></li><li><p><a href="./45-个体心理学和整体论">个体心理学和整体论</a></p></li><li><p><a href="./46-人际关系的终极目标">人际关系的终极目标</a></p></li><li><p><a href="./47-“拼命寻求认可”反而是以自我为中心？">“拼命寻求认可”反而是以自我为中心？</a></p></li><li><p><a href="./48-你不是世界的中心，只是世界地图的中心">你不是世界的中心，只是世界地图的中心</a></p></li><li><p><a href="./49-在更广阔的天地寻找自己的位置">在更广阔的天地寻找自己的位置</a></p></li><li><p><a href="./50-批评不好……表扬也不行？">批评不好……表扬也不行？</a></p></li><li><p><a href="./51-有鼓励才有勇气">有鼓励才有勇气</a></p></li><li><p><a href="./52-有价值就有勇气">有价值就有勇气</a></p></li><li><p><a href="./53-只要存在着，就有价值">只要存在着，就有价值</a></p></li><li><p><a href="./54-无论在哪里，都可以有平等的关系">无论在哪里，都可以有平等的关系</a></p></li><li><p><a href="./55-第五夜认真的人生“活在当下”">第五夜 认真的人生“活在当下”</a></p></li><li><p><a href="./56-过多的自我意识，反而会束缚自己">过多的自我意识，反而会束缚自己</a></p></li><li><p><a href="./57-不是肯定自我，而是接纳自我">不是肯定自我，而是接纳自我</a></p></li><li><p><a href="./58-信用和信赖有何区别？">信用和信赖有何区别？</a></p></li><li><p><a href="./59-工作的本质是对他人的贡献">工作的本质是对他人的贡献</a></p></li><li><p><a href="./60-年轻人也有胜过长者之处">年轻人也有胜过长者之处</a></p></li><li><p><a href="./61-“工作狂”是人生谎言">“工作狂”是人生谎言</a></p></li><li><p><a href="./62-从这一刻起，就能变得幸福">从这一刻起，就能变得幸福</a></p></li><li><p><a href="./63-追求理想者面前的两条路">追求理想者面前的两条路</a></p></li><li><p><a href="./64-甘于平凡的勇气">甘于平凡的勇气</a></p></li><li><p><a href="./65-人生是一连串的刹那">人生是一连串的刹那</a></p></li><li><p><a href="./66-舞动人生">舞动人生</a></p></li><li><p><a href="./67-最重要的是“此时此刻”">最重要的是“此时此刻”</a></p></li><li><p><a href="./68-对决“人生最大的谎言”">对决“人生最大的谎言”</a></p></li><li><p><a href="./69-人生的意义，由你自己决定">人生的意义，由你自己决定</a></p></li><li><p><a href="./70-后记">后记</a></p></li><li><p><a href="./71-作译者简介">作译者简介</a></p></li></ul>',9)])])}const c=i(r,[["render",f]]);export{d as __pageData,c as default};
